class Solution:
    def substringXorQueries(self, s: str, queries: list[list[int]]) -> list[list[int]]:
        best = {}
        n = len(s)
        for i in range(n):
            if s[i] == '0':
                cur = best.get(0)
                if cur is None or (cur[1] - cur[0], cur[0]) > (0, i):
                    best[0] = [i, i]
                continue
            v = 0
            for j in range(i, min(n, i + 30)):
                v = v * 2 + (s[j] == '1')
                cur = best.get(v)
                if cur is None or (cur[1] - cur[0], cur[0]) > (j - i, i):
                    best[v] = [i, j]
        return [best.get(f ^ sec, [-1, -1]) for f, sec in queries]

