class Solution {
public:
    vector<vector<int>> substringXorQueries(string s, vector<vector<int>>& queries) {
        unordered_map<long long, pair<int,int>> best;
        int n = s.size();
        for (int i = 0; i < n; i++) {
            if (s[i] == '0') {
                auto it = best.find(0);
                if (it == best.end()) best[0] = {i, i};
                continue;
            }
            long long v = 0;
            for (int j = i; j < min(n, i + 30); j++) {
                v = v * 2 + (s[j] == '1');
                auto it = best.find(v);
                if (it == best.end()) best[v] = {i, j};
            }
        }
        vector<vector<int>> ans;
        for (auto& q : queries) {
            long long v = (long long)q[0] ^ q[1];
            auto it = best.find(v);
            if (it != best.end()) ans.push_back({it->second.first, it->second.second});
            else ans.push_back({-1, -1});
        }
        return ans;
    }
};

