import java.util.*;
class Solution {
    public int[][] substringXorQueries(String s, int[][] queries) {
        Map<Integer, int[]> best = new HashMap<>();
        int n = s.length();
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '0') { best.putIfAbsent(0, new int[]{i, i}); continue; }
            int v = 0;
            for (int j = i; j < Math.min(n, i + 30); j++) {
                v = v * 2 + (s.charAt(j) - '0');
                best.putIfAbsent(v, new int[]{i, j});
            }
        }
        int[][] ans = new int[queries.length][];
        for (int k = 0; k < queries.length; k++) {
            int v = queries[k][0] ^ queries[k][1];
            int[] r = best.get(v);
            ans[k] = r == null ? new int[]{-1, -1} : r;
        }
        return ans;
    }
}

