var substringXorQueries = function(s, queries) {
    const best = new Map();
    const n = s.length;
    for (let i = 0; i < n; i++) {
        if (s[i] === '0') { if (!best.has(0)) best.set(0, [i, i]); continue; }
        let v = 0;
        for (let j = i; j < Math.min(n, i + 30); j++) {
            v = v * 2 + (s[j] === '1' ? 1 : 0);
            if (!best.has(v)) best.set(v, [i, j]);
        }
    }
    return queries.map(([f, sec]) => best.get(f ^ sec) || [-1, -1]);
};
